// Merge inputs from any trigger; unwrap webhook body if present
const inputs = $input.all().map(i => i.json || {});
const raw = inputs[0] || {};
// Webhook trigger wraps payload under "body"; cron/executeWorkflow pass fields at top
const merged = (raw && raw.body && typeof raw.body === 'object') ? { ...raw.body, ...raw } : raw;
const env = $env || {};
const runConfig = {
  run_id: `prospect-run-${Date.now()}`,
  started_at: new Date().toISOString(),
  linkedin_query: merged.linkedin_query || env.LINKEDIN_SEARCH_QUERY || 'operations manager ai automation latam',
  leads_per_run: Number(merged.leads_per_run || env.LEADS_PER_RUN || 25),
  fit_threshold: Number(merged.fit_threshold || env.LEAD_FIT_THRESHOLD || 70),
  dry_run: Boolean(merged.dry_run),
  test_leads: Array.isArray(merged.test_leads) ? merged.test_leads : null,
  tenant: 'levinnovation',
};
return [{ json: runConfig }];

const cfg = $('Initialize Run').first().json;
let rawLeads = [];

if (Array.isArray(cfg.test_leads) && cfg.test_leads.length > 0) {
  rawLeads = cfg.test_leads;
} else {
  const payload = $input.first().json || {};
  rawLeads = payload.data || payload.results || payload.items || payload.profiles || [];
}

const normalized = (Array.isArray(rawLeads) ? rawLeads : []).map((lead, index) => {
  const fullName = lead.full_name || lead.name || [lead.first_name, lead.last_name].filter(Boolean).join(' ');
  const company = lead.company_name || lead.company || lead.current_company || '';
  const role = lead.title || lead.headline || lead.position || '';
  const email = String(lead.email || lead.work_email || '').toLowerCase().trim();
  const linkedin = lead.profile_url || lead.linkedin_url || lead.url || '';
  const location = lead.location || lead.geo || '';
  const companyWebsite = lead.company_website || lead.website || '';
  const summary = lead.summary || lead.about || role;
  return {
    run_id: cfg.run_id,
    lead_id: `${cfg.run_id}-${index + 1}`,
    full_name: fullName,
    company,
    role,
    email,
    linkedin_url: linkedin,
    company_website: companyWebsite,
    location,
    summary,
    fit_threshold: cfg.fit_threshold,
    dry_run: cfg.dry_run,
    source_payload: lead,
  };
}).filter((l) => l.full_name && (l.linkedin_url || l.email));

// On empty: emit zero items so downstream branches don't fire on placeholder data
return normalized.map((lead) => ({ json: lead }));

const lead = $('Split In Batches').item.json;
const scrape = $input.first().json || {};
const tavilyAnswer = scrape.answer || '';
const tavilySnippets = Array.isArray(scrape.results)
  ? scrape.results.slice(0, 3).map(r => `- ${r.title}: ${r.content?.slice(0, 300) || ''}`).join('\n')
  : '';

const kb = `LEV Innovation - ICP & Differentiators
- ICP: SMB and mid-market organizations in LATAM with measurable efficiency goals
- Decision makers in operations, sales, customer success
- Use cases: AI sales automation, customer support copilots, deterministic AI workflow orchestration
- Differentiators: integration-first, human-in-the-loop, business-outcome focused`;

const chatInput = [
  'LEAD (datos normalizados):',
  JSON.stringify(lead, null, 2),
  '',
  'CONTEXTO DE EMPRESA (Tavily web search):',
  tavilyAnswer ? `Resumen: ${tavilyAnswer}` : '(sin resumen)',
  tavilySnippets || '(sin snippets)',
  '',
  'KNOWLEDGE BASE LEV:',
  kb,
  '',
  `Umbral minimo de fit_score: ${lead.fit_threshold || 70}`,
  '',
  'Devuelve SOLO el JSON final sin markdown, sin texto antes ni despues.',
].join('\n');

return [{ json: { ...lead, _chatInput: chatInput, _tavily_answer: tavilyAnswer } }];

const raw = $input.first().json || {};
const lead = $('Compose Agent Input').item.json;

function parseOutput(out) {
  if (out && typeof out === 'object' && !Array.isArray(out) && out.fit_score !== undefined) {
    return out;
  }
  let text = typeof out === 'string' ? out.trim() : JSON.stringify(out || {});
  if (text.startsWith('```')) {
    text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  }
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    text = text.slice(firstBrace, lastBrace + 1);
  }
  return JSON.parse(text);
}

let parsed;
let parseError = null;
try {
  parsed = parseOutput(raw.output ?? raw.text ?? raw);
} catch (e) {
  parseError = String(e);
  parsed = {
    fit_score: 0,
    qualification: 'No se pudo parsear salida del agente.',
    email_subject: 'LEV Innovation - propuesta de automatizacion',
    email_body: 'Hola, gracias por tu tiempo. Me gustaria compartir ideas de automatizacion aplicables a tu equipo.',
    linkedin_dm: 'Hola, vi tu perfil y creo que podriamos aportar valor con automatizacion AI aplicada.',
    internal_summary: 'Salida invalida del agente; se aplico fallback.',
  };
}

return [{
  json: {
    ...lead,
    fit_score: Number(parsed.fit_score || 0),
    qualification: String(parsed.qualification || ''),
    email_subject: String(parsed.email_subject || ''),
    email_body: String(parsed.email_body || ''),
    linkedin_dm: String(parsed.linkedin_dm || ''),
    internal_summary: String(parsed.internal_summary || ''),
    _parse_error: parseError,
  }
}];

const r = $input.first().json || {};
const lead = $('Wrap Company Input').item.json._lead_carry || {};
return [{ json: { ...lead, company_id: r?.company?.id || '', _twenty_company_ok: r?.ok === true } }];

